create table if not exists public.site_paginas(id bigint generated by default as identity primary key,titulo text not null,caminho text not null unique check(caminho like '/%'),ativa boolean not null default true,exige_login boolean not null default false,protecao_obrigatoria boolean not null default false,perfis_permitidos text[] not null default '{}',idiomas text[] not null default '{pt-BR,en-US,es}',categoria text,ordem integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(not protecao_obrigatoria or exige_login));
insert into public.site_paginas(titulo,caminho,exige_login,protecao_obrigatoria,categoria,ordem) values('Página inicial','/',false,false,'site',0),('Estratégias Patrimoniais','/estrategias-patrimoniais/',false,false,'site',10),('Mobilidade & Experiências','/mobilidade-experiencias/',false,false,'site',20),('Imóveis','/imoveis/',false,false,'site',30),('Administração','/admin/',true,true,'sistema',1000) on conflict(caminho) do update set protecao_obrigatoria=excluded.protecao_obrigatoria,exige_login=case when excluded.protecao_obrigatoria then true else site_paginas.exige_login end;
create table if not exists public.site_configuracoes(id integer primary key default 1 check(id=1),idioma_padrao text not null default 'pt-BR',idiomas_ativos text[] not null default '{pt-BR,en-US,es}',moeda_pt text not null default 'BRL',moeda_en text not null default 'USD',moeda_es text not null default 'USD',cambio_automatico boolean not null default true,tipo_ptax text not null default 'venda' check(tipo_ptax in('compra','venda')),margem_cambio_percentual numeric(8,4) not null default 0,cotacao_manual numeric(14,6) check(cotacao_manual is null or cotacao_manual>0),updated_at timestamptz not null default now());insert into public.site_configuracoes(id)values(1)on conflict(id)do nothing;
create table if not exists public.cotacoes_cambio(id bigint generated by default as identity primary key,par text not null default 'USD/BRL',cotacao_compra numeric(14,6) not null check(cotacao_compra>0),cotacao_venda numeric(14,6) not null check(cotacao_venda>0),data_cotacao date not null,fonte text not null default 'BCB PTAX',oficial boolean not null default true,created_at timestamptz not null default now(),unique(par,data_cotacao,fonte));create index if not exists cotacoes_cambio_data_idx on public.cotacoes_cambio(par,data_cotacao desc);
create table if not exists public.perfis_usuario(user_id uuid primary key references auth.users(id)on delete cascade,perfil text not null default 'cliente' check(perfil in('admin','equipe','cliente')),ativo boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());create or replace function public.is_admin()returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.perfis_usuario where user_id=auth.uid()and perfil='admin'and ativo)$$;
create or replace view public.cotacao_usd_brl_atual with(security_invoker=true)as select coalesce(c.cotacao_manual,case c.tipo_ptax when'compra'then x.cotacao_compra else x.cotacao_venda end)*(1+c.margem_cambio_percentual/100)cotacao,x.data_cotacao,c.cotacao_manual is not null as manual from public.site_configuracoes c left join lateral(select*from public.cotacoes_cambio where par='USD/BRL'order by data_cotacao desc,created_at desc limit 1)x on true where c.id=1;
alter table public.site_paginas enable row level security;alter table public.site_configuracoes enable row level security;alter table public.cotacoes_cambio enable row level security;alter table public.perfis_usuario enable row level security;drop policy if exists "paginas leitura publica" on public.site_paginas;create policy "paginas leitura publica" on public.site_paginas for select using(true);drop policy if exists "paginas admin" on public.site_paginas;create policy "paginas admin" on public.site_paginas for all to authenticated using(public.is_admin())with check(public.is_admin()and(not protecao_obrigatoria or exige_login));drop policy if exists "config leitura publica" on public.site_configuracoes;create policy "config leitura publica" on public.site_configuracoes for select using(true);drop policy if exists "config admin" on public.site_configuracoes;create policy "config admin" on public.site_configuracoes for all to authenticated using(public.is_admin())with check(public.is_admin());drop policy if exists "cambio leitura publica" on public.cotacoes_cambio;create policy "cambio leitura publica" on public.cotacoes_cambio for select using(true);drop policy if exists "cambio admin" on public.cotacoes_cambio;create policy "cambio admin" on public.cotacoes_cambio for all to authenticated using(public.is_admin())with check(public.is_admin());drop policy if exists "perfil proprio" on public.perfis_usuario;create policy "perfil proprio" on public.perfis_usuario for select to authenticated using(user_id=auth.uid()or public.is_admin());drop policy if exists "perfis admin" on public.perfis_usuario;create policy "perfis admin" on public.perfis_usuario for all to authenticated using(public.is_admin())with check(public.is_admin());grant select on public.cotacao_usd_brl_atual to anon,authenticated;
